"use strict";

// Kisolo server code (v2 Game API).
// Kisolo (also Chisolo / Cisolo), the four-row mancala of the Luba, Lulua
// and Songye peoples of the Congo, in the form described by the Mancala
// World wiki article "Kisolo" (after Townshend 1977 and Russ, The Complete
// Mancala Games Book, 2000, pp. 120-121), cross-checked against the Ludii
// Kisolo ruleset (Townshend 1977). Fixed variant, documented everywhere in
// this package:
//   * Board: four rows of 7 holes. Each player owns the two rows on their
//     own side: a back (outer) row and a front (inner) row that faces the
//     opponent's front row. Three seeds start in each of the 28 holes
//     (84 seeds in all). Seat 0 moves first.
//   * A player only ever sows on their own two rows, counterclockwise
//     around them (as seen from above).
//   * Capture at the start of a turn (compulsory): if one of your front
//     holes and the opponent's front hole directly opposite it both hold
//     seeds, you must capture. Choose such a hole: take all the seeds from
//     the opponent's front hole and from the opponent's back hole behind
//     it, and sow those seeds on your own side, dropping the first seed
//     into your own front hole that faced them. Only the opponent's seeds
//     are taken; your own front hole keeps the seeds it holds (the
//     Mancala World text, read literally; some simplified accounts also
//     sweep the facing hole's own seeds into the sowing, which this
//     variant does not).
//   * Sowing (when no capture is open): empty one of your own holes and
//     sow its seeds one by one counterclockwise into the following holes
//     of your own rows.
//   * Continuation ("pussa kanawa" relay): whenever a sowing hand runs
//     out, look at the hole after the one that took the last seed. If the
//     last seed landed in a hole that already held seeds, and that next
//     hole is one of your front holes holding seeds whose opposite front
//     hole holds seeds, capture those opposite seeds as above, sowing
//     them starting in that front hole. Otherwise, if the next hole holds
//     seeds, pick them all up and keep sowing. The move ends when the
//     next hole is empty.
//   * Winning: a capture that takes the last seeds of the opponent's
//     front row wins the game at once, however many seeds the opponent
//     still has in the back row. Captured seeds are sown on the
//     capturer's side, never banked, so all 84 seeds stay on the board.
//   * Draws: a move that never ends (perpetual sowing) is a draw; as a
//     house limit for this digital version, a game still open after 300
//     completed moves is also a draw.
//   * Settling with a pot follows the usual form: the winner, if human,
//     takes the pot; if the winner is a computer, the only human gets
//     the pot back; a drawn game splits the pot between the humans.
//
// Board layout (rows as seen from above, seat 0 at the bottom):
//   row 0: seat 0 back (outer) holes, columns 0..6 left to right
//   row 1: seat 0 front (inner) holes, columns 0..6
//   row 2: seat 1 front (inner) holes, columns 0..6
//   row 3: seat 1 back (outer) holes, columns 0..6
// A hole index is row * 7 + column. Seat 0's front hole at column c faces
// seat 1's front hole at column c. Sowing circuits (counterclockwise):
//   seat 0: outer row left to right, then front row right to left.
//   seat 1: outer row right to left, then front row left to right.
// A move is {"pit": 0..27}: the absolute hole index where the move
// starts (a front hole to capture from, or any own hole to sow). The
// opening position is fixed (3 seeds per hole), so newMatch never calls
// ctx.random() and is fully verifiable.

const COLS = 7;
const TOTAL_SEEDS = 84;
const MOVE_LIMIT = 300;
const SOW_LIMIT = 2000;

const CIRCUITS = [
  [0, 1, 2, 3, 4, 5, 6, 13, 12, 11, 10, 9, 8, 7],
  [27, 26, 25, 24, 23, 22, 21, 14, 15, 16, 17, 18, 19, 20],
];

function innerHole(seat, col) { return seat === 0 ? 7 + col : 14 + col; }
function enemyInnerHole(seat, col) { return seat === 0 ? 14 + col : 7 + col; }
function enemyOuterHole(seat, col) { return seat === 0 ? 21 + col : col; }
function isInnerHole(seat, hole) {
  const row = Math.floor(hole / COLS);
  return seat === 0 ? row === 1 : row === 2;
}
function ownerOf(hole) { return hole < 14 ? 0 : 1; }
function flatOf(state) {
  const flat = [];
  for (let r = 0; r < 4; r++) for (let c = 0; c < COLS; c++) flat.push(state.rows[r][c]);
  return flat;
}
function rowsOf(flat) {
  return [flat.slice(0, 7), flat.slice(7, 14), flat.slice(14, 21), flat.slice(21, 28)];
}
function copyState(state) {
  return {
    rows: state.rows.map(function (row) { return row.slice(); }),
    winner: state.winner,
    over: state.over,
    to_move: state.to_move,
    moves: state.moves,
  };
}
function totalSeeds(state) {
  return flatOf(state).reduce(function (a, b) { return a + b; }, 0);
}
function innerRowSum(flat, seat) {
  let n = 0;
  for (let c = 0; c < COLS; c++) n += flat[innerHole(seat, c)];
  return n;
}
function sideSum(flat, seat) {
  let n = 0;
  const circuit = CIRCUITS[seat];
  for (let i = 0; i < circuit.length; i++) n += flat[circuit[i]];
  return n;
}
// The columns where a capture is open for `seat`: both front holes of the
// file hold seeds.
function captureFiles(flat, seat) {
  const files = [];
  for (let c = 0; c < COLS; c++) {
    if (flat[innerHole(seat, c)] > 0 && flat[enemyInnerHole(seat, c)] > 0) files.push(c);
  }
  return files;
}
// The holes a seat may legally start a move from, as absolute indices.
// When a capture is open it is compulsory: only the capturing front
// holes are legal.
function legalPits(state, seat) {
  const flat = flatOf(state);
  const caps = captureFiles(flat, seat);
  if (caps.length > 0) {
    return caps.map(function (c) { return innerHole(seat, c); });
  }
  const out = [];
  const circuit = CIRCUITS[seat];
  for (let i = 0; i < circuit.length; i++) {
    if (flat[circuit[i]] > 0) out.push(circuit[i]);
  }
  return out;
}
function takeCapture(flat, seat, col) {
  const a = enemyInnerHole(seat, col);
  const b = enemyOuterHole(seat, col);
  const n = flat[a] + flat[b];
  flat[a] = 0;
  flat[b] = 0;
  return n;
}
// Sow one hand of `count` seeds, the first seed dropping into
// `firstDrop`, the rest into the following holes of the seat's circuit.
// Returns { limit, lastHole, lastWasOccupied }: lastWasOccupied tells
// whether the hole that took the last seed already held seeds before it.
// `budget` counts the seeds sown inside the whole move; past SOW_LIMIT
// the sowing is perpetual: the rest of the hand is left in the current
// hole (so no seed is lost) and the move is a draw.
function sowHand(flat, seat, firstDrop, count, budget) {
  const circuit = CIRCUITS[seat];
  let pos = circuit.indexOf(firstDrop);
  let remaining = count;
  let lastHole = firstDrop;
  let lastWasOccupied = false;
  while (remaining > 0) {
    const hole = circuit[pos];
    if (remaining === 1) lastWasOccupied = flat[hole] > 0;
    flat[hole] += 1;
    lastHole = hole;
    remaining -= 1;
    budget.n += 1;
    if (budget.n > SOW_LIMIT) {
      flat[hole] += remaining;
      return { limit: true, lastHole: lastHole, lastWasOccupied: lastWasOccupied };
    }
    pos = (pos + 1) % circuit.length;
  }
  return { limit: false, lastHole: lastHole, lastWasOccupied: lastWasOccupied };
}
// Resolve one full move on a copy of the state. Returns
// { state, captured, won, draw }: captured counts the seeds taken from
// the opponent during the move; won is true when a capture emptied the
// opponent's front row (that capture wins at once; its seeds are still
// sown onto the winner's side as one final hand, with no continuation,
// so all 84 seeds stay on the board); draw is true on perpetual sowing.
function resolveMove(state, seat, pit) {
  const next = copyState(state);
  const flat = flatOf(next);
  const circuit = CIRCUITS[seat];
  const budget = { n: 0 };
  let captured = 0;
  let won = false;
  let draw = false;
  let hand = null;
  if (captureFiles(flat, seat).length > 0) {
    const col = pit - innerHole(seat, 0);
    const taken = takeCapture(flat, seat, col);
    captured += taken;
    hand = { firstDrop: pit, count: taken, final: innerRowSum(flat, 1 - seat) === 0 };
  } else {
    const n = flat[pit];
    flat[pit] = 0;
    hand = { firstDrop: circuit[(circuit.indexOf(pit) + 1) % circuit.length], count: n };
  }
  while (!won && hand) {
    const r = sowHand(flat, seat, hand.firstDrop, hand.count, budget);
    if (r.limit) { draw = true; break; }
    if (hand.final) { won = true; break; }
    const nextHole = circuit[(circuit.indexOf(r.lastHole) + 1) % circuit.length];
    if (r.lastWasOccupied && isInnerHole(seat, nextHole) && flat[nextHole] > 0) {
      const col = nextHole - innerHole(seat, 0);
      if (flat[enemyInnerHole(seat, col)] > 0) {
        const taken = takeCapture(flat, seat, col);
        captured += taken;
        hand = { firstDrop: nextHole, count: taken, final: innerRowSum(flat, 1 - seat) === 0 };
        continue;
      }
    }
    if (flat[nextHole] > 0) {
      const n = flat[nextHole];
      flat[nextHole] = 0;
      hand = { firstDrop: circuit[(circuit.indexOf(nextHole) + 1) % circuit.length], count: n };
      continue;
    }
    hand = null;
  }
  next.rows = rowsOf(flat);
  return { state: next, captured: captured, won: won, draw: draw };
}
function settle(state, ctx) {
  if (ctx.pot === 0) return {};
  const humans = ctx.players.filter(function (p) { return p.kind === "human"; });
  if (humans.length === 0) return {};
  if (state.winner === -1) {
    const share = Math.floor(ctx.pot / humans.length);
    const payouts = {};
    humans.forEach(function (p, i) {
      payouts[p.id] = share + (i === 0 ? ctx.pot - share * humans.length : 0);
    });
    return payouts;
  }
  const winnerPlayer = ctx.players[state.winner];
  if (winnerPlayer && winnerPlayer.kind === "human") {
    const payouts = {};
    payouts[winnerPlayer.id] = ctx.pot;
    return payouts;
  }
  const payouts = {};
  payouts[humans[0].id] = ctx.pot;
  return payouts;
}

const game = {
  newMatch(ctx) {
    const rows = [];
    for (let r = 0; r < 4; r++) {
      const row = [];
      for (let c = 0; c < COLS; c++) row.push(3);
      rows.push(row);
    }
    const state = {
      rows: rows,
      winner: null,
      over: false,
      to_move: 0,
      moves: 0,
    };
    return { state: state, turn: [ctx.players[0].id] };
  },

  applyMove(state, playerId, move, ctx) {
    if (!move || typeof move !== "object" || Array.isArray(move)) {
      throw new InvalidMove("send a pit from 0 to 27");
    }
    if (state.over) {
      throw new InvalidMove("the game is over");
    }
    const seat = ctx.players.findIndex(function (p) { return p.id === playerId; });
    if (seat < 0 || seat !== state.to_move) {
      throw new InvalidMove("it is not your turn");
    }
    if (Object.keys(move).length !== 1 || !Number.isInteger(move.pit) || move.pit < 0 || move.pit > 27) {
      throw new InvalidMove("send a pit from 0 to 27");
    }
    if (ownerOf(move.pit) !== seat) {
      throw new InvalidMove("that pit is not yours");
    }
    const flat = flatOf(state);
    if (captureFiles(flat, seat).length > 0 && legalPits(state, seat).indexOf(move.pit) < 0) {
      throw new InvalidMove("you must capture");
    }
    if (flat[move.pit] === 0) {
      throw new InvalidMove("that pit is empty");
    }
    const resolved = resolveMove(state, seat, move.pit);
    const next = resolved.state;
    next.moves = state.moves + 1;
    if (resolved.won) {
      next.over = true;
      next.winner = seat;
      next.to_move = seat;
      return { state: next, turn: null, payouts: settle(next, ctx) };
    }
    if (resolved.draw || next.moves >= MOVE_LIMIT) {
      next.over = true;
      next.winner = -1;
      next.to_move = seat;
      return { state: next, turn: null, payouts: settle(next, ctx) };
    }
    next.to_move = 1 - seat;
    return { state: next, turn: [ctx.players[1 - seat].id] };
  },

  computerMove(state, playerId, ctx) {
    const seat = ctx.players.findIndex(function (p) { return p.id === playerId; });
    const options = legalPits(state, seat);
    if (options.length === 0) return { pit: seat === 0 ? 0 : 14 };
    let best = options[0];
    let bestScore = -Infinity;
    for (const pit of options) {
      const resolved = resolveMove(state, seat, pit);
      const flat = flatOf(resolved.state);
      let score = resolved.captured * 100
        + sideSum(flat, seat)
        + innerRowSum(flat, seat) * 2
        - innerRowSum(flat, 1 - seat) * 2;
      if (resolved.won) score += 100000;
      if (resolved.draw) score -= 50000;
      if (score > bestScore) { bestScore = score; best = pit; }
    }
    return { pit: best };
  },

  randomMove(state, playerId, ctx) {
    const seat = ctx.players.findIndex(function (p) { return p.id === playerId; });
    const options = legalPits(state, seat);
    if (options.length === 0) return { pit: seat === 0 ? 0 : 14 };
    return { pit: options[Math.floor(ctx.random() * options.length)] };
  },

  viewFor(state, playerId, ctx) {
    // Kisolo has no hidden information: every viewer sees the whole board.
    return {
      rows: state.rows.map(function (row) { return row.slice(); }),
      winner: state.winner,
      over: state.over,
      to_move: state.to_move,
      moves: state.moves,
    };
  },
};

